  const archived=await seed('user','announcement',true,'Ukončené oznámení v archivu');const archiveResponse=await fetch(origin+'/qa/archive-notification?group=web&identifier='+archived.id,{method:'POST'});assert(archiveResponse.ok);await p.reload();await p.locator('#notification-nav-entry').waitFor();await until(async()=>await banner.count()===0);await p.locator('#notification-nav-entry').click();const archiveCard=dialog(p).locator('[data-notification-id="'+archived.id+'"]');await archiveCard.getByText('Archivováno · již nevyžaduje potvrzení',{exact:true}).waitFor();await archiveCard.getByRole('button',{name:'Otevřít',exact:true}).click();await dialog(p).getByText(archived.body,{exact:true}).waitFor();assert.equal(await dialog(p).getByRole('button',{name:'Potvrdit přečtení',exact:true}).count(),0);assert.equal(await dialog(p).getByRole('button',{name:'Rozumím',exact:true}).count(),0);await save(p,'05-archived-snapshot');await close(p);checks.push('Expired targeted announcement retained as archived snapshot with no badge or acknowledgment action');
